// One row per review, stamped with the run date and keyed by review ID, so
// the sheet reads as a review history: an ID in this week's rows that is
// missing from last week's is a new review.
//
// The source returns product IDs but no app name, so the friendly label comes
// from the list you set in the input node.
const weekOf = $now.toFormat('yyyy-MM-dd');
const apps = $('Set the apps to watch').first().json.apps || [];
const nameById = Object.fromEntries(apps.map((a) => [String(a.id), a.name]));

const clip = (s, n) => {
  const v = String(s || '').replace(/\s+/g, ' ').trim();
  return v.length > n ? v.slice(0, n - 3) + '...' : v;
};

// reviewed_version arrives as "Version 26.30.78"; the prefix is noise in a
// column that is already called App version.
const version = (v) => String(v || '').replace(/^Version\s+/i, '').trim();

// Measured over 60 rows across two apps: reviews_for_current_version is not
// comparable between apps (19,154,786 for one, 9 for the other), so it is not
// mapped rather than shipping a number that reads as the same thing twice.
return $input.all().map((item) => {
  const r = item.json;
  const rating = typeof r.rating === 'number' ? r.rating : '';
  return {
    json: {
      'Week of': weekOf,
      App: nameById[String(r.product_id)] || r.product_id || '',
      'Product ID': r.product_id || '',
      Store: r.app_country || '',
      Platform: r.app_platform || '',
      'Review ID': r.review_id || '',
      Rank: r.position_global ?? '',
      Rating: rating,
      Critical: rating !== '' && rating <= 2 ? 'YES' : '',
      'Review date': r.review_date_iso || '',
      'App version': version(r.reviewed_version),
      Title: clip(r.review_title, 140),
      Review: clip(r.review_text, 400),
      Author: clip(r.author_name, 80),
    },
  };
});

// The Summarize node names its outputs after the aggregation and the field
// (average_Rating and so on). Rather than hard coding those names, each value
// is found by matching the aggregation prefix, so a rename upstream cannot
// silently blank a column.
const weekOf = $now.toFormat('yyyy-MM-dd');
const reviews = $('One row per review').all().map((i) => i.json);

const pick = (obj, prefix) => {
  const key = Object.keys(obj).find((k) => k.toLowerCase().startsWith(prefix));
  return key === undefined ? '' : obj[key];
};

const round1 = (v) => {
  const n = Number(v);
  return isFinite(n) ? Math.round(n * 10) / 10 : '';
};

return $input.all().map((item) => {
  const s = item.json;
  const app = s.App ?? '';
  const mine = reviews.filter((r) => r.App === app);
  const critical = mine.filter((r) => r.Critical === 'YES').length;
  const fiveStar = mine.filter((r) => r.Rating === 5).length;
  const total = mine.length;
  const versions = [...new Set(mine.map((r) => r['App version']).filter(Boolean))];

  return {
    json: {
      'Week of': weekOf,
      App: app,
      'Reviews this week': pick(s, 'count_') || total,
      'Average rating': round1(pick(s, 'average_')),
      'Lowest rating': pick(s, 'min_'),
      'Highest rating': pick(s, 'max_'),
      'Critical (1-2 star)': critical,
      'Critical %': total ? Math.round((critical / total) * 100) : '',
      'Five star': fiveStar,
      'Five star %': total ? Math.round((fiveStar / total) * 100) : '',
      'Versions seen': versions.join(', '),
    },
  };
});

